阅读下列代码，计算程序执行后变量 total_bad 的整数值。
struct Box {
int count;
int bad;
};
struct Box stations[2] = {{10, 2}, {20, 5}};
struct Box *p = stations;
p->bad = p->bad + 1;
(p + 1)->bad = (p + 1)->bad + 3;
int total_bad = stations[0].bad + stations[1].bad;

